-- coroutine.status in every state: suspended, running, normal and dead.
local outer, inner
inner = coroutine.create(function()
  print("inner sees inner", coroutine.status(inner))
  print("inner sees outer", coroutine.status(outer))
  coroutine.yield()
  print("inner again", coroutine.status(inner), coroutine.status(outer))
end)
outer = coroutine.create(function()
  print("outer sees outer", coroutine.status(outer))
  print("outer sees inner", coroutine.status(inner))
  coroutine.resume(inner)
  print("after inner yield", coroutine.status(inner))
  coroutine.yield()
  coroutine.resume(inner)
  print("after inner end", coroutine.status(inner))
end)
print("before", coroutine.status(outer), coroutine.status(inner))
coroutine.resume(outer)
print("outer yielded", coroutine.status(outer), coroutine.status(inner))
coroutine.resume(outer)
print("outer done", coroutine.status(outer), coroutine.status(inner))
-- dead after an error too
local bad = coroutine.create(function() error("x") end)
print(coroutine.resume(bad))
print(coroutine.status(bad))
-- the main thread, from inside a coroutine
local main = coroutine.running()
local co = coroutine.create(function() return coroutine.status(main) end)
print(coroutine.resume(co))
print(coroutine.status(main))
return coroutine.status(co)
